const body = $input.first().json;
const results = body.results || [];

if (results.length === 0) {
  throw new Error('OpenAQ no devolvio estaciones. Revisa la API key o el bbox.');
}

return results.map((loc) => ({
  json: {
    codigo_externo: String(loc.id),
    nombre: (loc.name || 'SIN NOMBRE').toUpperCase(),
    tipo: 'calidad_aire',
    zona: null,
    latitud: loc.coordinates ? loc.coordinates.latitude : null,
    longitud: loc.coordinates ? loc.coordinates.longitude : null,
    proveedor: 'OpenAQ',
  },
}));

// ============================================================
// FIX: el endpoint /latest NO trae el nombre del parametro
// directamente (solo sensorsId). Se construye un mapa
// sensorId -> {parametro, unidad} a partir de loc.sensors[]
// en la respuesta original de /locations.
// ============================================================
const locsResponse = $('OpenAQ: listar estaciones PE').first().json;
const ubicaciones = locsResponse.results || [];

const sensorInfo = {};
for (const loc of ubicaciones) {
  const sensores = loc.sensors || [];
  for (const s of sensores) {
    sensorInfo[s.id] = {
      parametro: ((s.parameter && (s.parameter.name || s.parameter.id)) || 'desconocido').toLowerCase(),
      unidad: (s.parameter && s.parameter.units) || 'ug/m3',
    };
  }
}

const estaciones = $('Upsert estaciones').all();
const respuestas = $input.all();
const filas = [];

for (let i = 0; i < respuestas.length; i++) {
  const resp = respuestas[i].json;
  const estacionId = estaciones[i] ? estaciones[i].json.id : null;
  if (!estacionId) continue;

  const resultados = resp.results || [];
  for (const r of resultados) {
    const info = sensorInfo[r.sensorsId] || {};
    const parametro = info.parametro || 'desconocido';
    const valor = typeof r.value === 'number' ? r.value : null;
    const unidad = info.unidad || 'ug/m3';
    const medidoEn = (r.datetime && (r.datetime.utc || r.datetime.local)) || r.datetime || null;

    // Se descarta si falta el valor, la fecha, o no se pudo mapear el parametro
    // (mejor perder el dato que insertarlo como 'desconocido')
    if (valor === null || !medidoEn || parametro === 'desconocido') continue;

    filas.push({
      json: {
        estacion_id: estacionId,
        parametro,
        valor,
        unidad,
        medido_en: medidoEn,
        payload_crudo: JSON.stringify(r),
      },
    });
  }
}

return filas;

const RANGOS = {
  pm25: [0, 1000], pm10: [0, 1500], no2: [0, 2000],
  so2: [0, 2000], o3: [0, 1000], co: [0, 50000],
};

return $input.all().filter((item) => {
  const { parametro, valor } = item.json;
  const rango = RANGOS[parametro];
  if (!rango) return true;
  return valor >= rango[0] && valor <= rango[1];
});

// ============================================================
// ADVERTENCIA: los valores de UMBRALES_ECA son referenciales,
// tomados de conocimiento general del D.S. 003-2017-MINAM.
// VERIFICAR contra la norma vigente y las unidades reales de
// mediciones_aire.unidad antes de usar en produccion.
//
// Mapeo hacia las columnas REALES de alertas_anomalias:
// - valor_registrado = el valor que disparo la alerta
// - umbral_base = el limite ECA (si excede la norma) o el
//                 promedio historico (si es atipico estadistico)
// - desviacion  = el z-score calculado
// analisis_llm, notificado_telegram, notificado_correo quedan
// sin llenar: pertenecen a HU-10, fuera de esta HU (sin IA).
// ============================================================
const UMBRALES_ECA = {
  pm25: 50,
  pm10: 100,
  so2: 250,
  no2: 200,
  o3: 100,
  co: 10000,
};

const Z_UMBRAL = 2.5;

const filas = $input.all().map((i) => i.json);
const anomalias = [];

for (const fila of filas) {
  const zScore = Number(fila.z_score);
  const valorActual = Number(fila.valor_actual);
  const promedioHistorico = Number(fila.promedio);
  const umbralNormativo = UMBRALES_ECA[fila.parametro];

  const excedeNormativo = umbralNormativo !== undefined && valorActual > umbralNormativo;
  const esAtipico = Math.abs(zScore) > Z_UMBRAL;

  if (!excedeNormativo && !esAtipico) continue;

  const severidad = excedeNormativo ? 'alta' : 'moderada';

  anomalias.push({
    json: {
      estacion_id: fila.estacion_id,
      parametro: fila.parametro,
      valor_registrado: valorActual,
      umbral_base: excedeNormativo ? umbralNormativo : promedioHistorico,
      desviacion: Number(zScore.toFixed(2)),
      severidad,
    },
  });
}

return anomalias;

const original = $('Evaluar umbrales y clasificar severidad').item.json;

// severidad='alta' siempre corresponde a exceso del limite normativo ECA-aire;
// severidad='moderada' siempre corresponde a desviacion estadistica (promedio historico).
// Esto se determina aqui, en codigo, para no depender de que el LLM lo infiera bien.
const esExcesoNormativo = original.severidad === 'alta';
const etiquetaReferencia = esExcesoNormativo
  ? 'Limite normativo ECA-aire'
  : 'Promedio historico de la estacion';

const sistema = 'Redactas un analisis breve (maximo 3 oraciones) de una anomalia '
  + 'de calidad del aire detectada estadisticamente. Describe UNICAMENTE la '
  + 'desviacion numerica observada. Usa EXACTAMENTE el termino "limite normativo '
  + 'ECA-aire" cuando el valor supere la norma legal, o "promedio historico" '
  + 'cuando se trate de una desviacion estadistica sin exceder la norma. '
  + 'NUNCA uses la palabra "umbral" de forma ambigua sin aclarar a cual de los '
  + 'dos casos te refieres. NUNCA inventes una causa externa (trafico, incendios, '
  + 'clima, etc.) que no se te haya proporcionado como dato: si no tienes '
  + 'informacion sobre la causa, no la menciones ni la sugieras.';

const usuario = `Parametro: ${original.parametro}\n`
  + `Valor registrado: ${original.valor_registrado}\n`
  + `${etiquetaReferencia}: ${original.umbral_base}\n`
  + `Desviacion (z-score): ${original.desviacion}\n`
  + `Severidad: ${original.severidad}\n`
  + `Tipo de anomalia: ${esExcesoNormativo ? 'excede el limite legal' : 'desviacion estadistica atipica, dentro de lo legal'}`;

return {
  json: {
    estacion_id: original.estacion_id,
    parametro: original.parametro,
    valor_registrado: original.valor_registrado,
    umbral_base: original.umbral_base,
    desviacion: original.desviacion,
    severidad: original.severidad,
    groq_payload: {
      model: 'openai/gpt-oss-120b',
      messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }],
      temperature: 0.3, max_tokens: 200, reasoning_effort: 'none',
    },
    gemini_payload: {
      contents: [{ parts: [{ text: `${sistema}\n\n${usuario}` }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 150 },
    },
  },
};

const r = $input.item.json;
const original = $('Preparar prompt: analisis de anomalia').item.json;

let texto = 'No fue posible generar el analisis automatico.';
if (r.choices && r.choices[0]) texto = r.choices[0].message.content.trim();
else if (r.candidates && r.candidates[0]) texto = r.candidates[0].content.parts[0].text.trim();

return {
  json: {
    estacion_id: original.estacion_id,
    parametro: original.parametro,
    valor_registrado: original.valor_registrado,
    umbral_base: original.umbral_base,
    desviacion: original.desviacion,
    severidad: original.severidad,
    analisis_llm: texto,
  },
};

const original = $json;

return {
  json: {
    descartado: true,
    motivo: 'Ya existe una alerta reciente para esta estacion y parametro (ultima hora)',
    estacion_id: original.estacion_id,
    parametro: original.parametro,
  },
};
